int a = 5, b;

b = ++a;   /* a를 6으로 만든 뒤, b에 6 */
printf("%d %d\n", a, b);  /* 6 6 */

a = 5;
b = a++;   /* b에 5를 준 뒤, a를 6으로 */
printf("%d %d\n", a, b);  /* 6 5 */

int x = 3;
printf("%d\n", x++);
printf("%d\n", x);
printf("%d\n", ++x);

int a = 5, b = 3;
printf("%d\n", a > b);    /* 1 */
printf("%d\n", a == b);   /* 0 */

int a = 0;
int r = (a != 0) && (10 / a > 1);
printf("%d\n", r);

int sum = 7, n = 2;
printf("%.2f\n", (double)(sum / n));
printf("%.2f\n", (double)sum / n);

